import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";import{D as i,E as a,T as o,w as s}from"./chunks/assets.DjpLsfX1.js";var c=JSON.parse(`{"title":"Product Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/06-product.md","filePath":"02-consumer/06-product.md"}`),l={name:`02-consumer/06-product.md`};function u(n,c,l,u,d,f){return r(),t(`div`,null,[...c[0]||=[e(`<h1 id="product-management-guide" tabindex="-1">Product Management Guide <a class="header-anchor" href="#product-management-guide" aria-label="Permalink to “Product Management Guide”">​</a></h1><p>This guide explains how to create and edit a product in the admin panel. The product form is designed as a four-step wizard so that basic information, images, additional details, and product inventory can be managed in separate sections.</p><p>Some information in this form is interdependent; for example, a product&#39;s inventory count can be calculated from the options defined in Properties Meta. Attachments can also be made available to everyone or exclusively to customers who have purchased the product.</p><h2 id="overview-of-the-steps" tabindex="-1">Overview of the Steps <a class="header-anchor" href="#overview-of-the-steps" aria-label="Permalink to “Overview of the Steps”">​</a></h2><p>Step 1 - Basic Data<br> Product name and URL, price, main category, creators, description, SEO keyword, and product-specific template settings.</p><p>Step 2 - Medias<br> Upload product images, select the featured image, and manage gallery images.</p><p>Step 3 - Additional Data<br> Inventory, publication status, tags, other categories, virtual or downloadable product settings, specification table, discounts, attachments, and Schema Markup.</p><p>Step 4 - Quantities<br> Define different product options based on features such as color or storage capacity, along with the quantity and price of each option.</p><h2 id="step-1-basic-product-data" tabindex="-1">Step 1: Basic Product Data <a class="header-anchor" href="#step-1-basic-product-data" aria-label="Permalink to “Step 1: Basic Product Data”">​</a></h2><p><img src="`+i+`" alt="product1.webp" width="1849" height="1729"> Image reference: Fourth submitted image - Basic Data form</p><p>Enter the product&#39;s main information in this step. This information is used on the product page, in search and categories, and in SEO-related sections.</p><h3 id="basic-information-fields" tabindex="-1">Basic Information Fields <a class="header-anchor" href="#basic-information-fields" aria-label="Permalink to “Basic Information Fields”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td>The product name displayed to customers.</td></tr><tr><td>Slug</td><td>The text identifier used in the product URL. If the form supports it, you can leave this blank to have it generated automatically.</td></tr><tr><td>Base price</td><td>The product&#39;s base price. For products with quantity options, the price can be calculated from those options.</td></tr><tr><td>Purchase price</td><td>The product&#39;s purchase price, used to calculate the gross profit margin.</td></tr><tr><td>Creators</td><td>Creators, brands, or people associated with the product.</td></tr><tr><td>Main product category</td><td>The product&#39;s main category.</td></tr><tr><td>SKU</td><td>The product&#39;s inventory identifier; it must be unique if provided.</td></tr><tr><td>Status</td><td>The product&#39;s publication status: draft or published.</td></tr><tr><td>Excerpt</td><td>A short product summary for display in various sections of the site and for SEO-related uses.</td></tr><tr><td>Description Text</td><td>The full product description, which can be edited with a Rich Text Editor.</td></tr><tr><td>Keyword [SEO]</td><td>The target keyword for SEO analysis and optimization.</td></tr></tbody></table><h3 id="seo-analysis" tabindex="-1">SEO Analysis <a class="header-anchor" href="#seo-analysis" aria-label="Permalink to “SEO Analysis”">​</a></h3><p>The product description editor includes SEO evaluation features. After you enter content and a keyword, the system can display an SEO score, suggestions for improvements, and metrics such as content length, keyword usage, average sentence length, and paragraph structure.</p><p>This evaluation can help improve content quality. However, the displayed score alone does not guarantee better search engine rankings.</p><h3 id="product-specific-template-settings" tabindex="-1">Product-Specific Template Settings <a class="header-anchor" href="#product-specific-template-settings" aria-label="Permalink to “Product-Specific Template Settings”">​</a></h3><p>The gray button with a color-palette icon at the top of the form lets you configure a custom template for that product.</p><ul><li>These settings are used to customize the display of the selected product.</li><li>Its changes are separate from the custom template settings for other products and apply only to that product.</li><li>Use this feature when the selected product needs to be displayed differently from the site&#39;s general template.</li></ul><h2 id="step-2-product-media-and-images" tabindex="-1">Step 2: Product Media and Images <a class="header-anchor" href="#step-2-product-media-and-images" aria-label="Permalink to “Step 2: Product Media and Images”">​</a></h2><p><img src="`+a+`" alt="product2.webp" width="1858" height="1075"> Image reference: Third submitted image - Medias form</p><p>This step is designed for uploading and managing product images. Images can be used in the product gallery and as the featured image.</p><h3 id="uploading-images" tabindex="-1">Uploading Images <a class="header-anchor" href="#uploading-images" aria-label="Permalink to “Uploading Images”">​</a></h3><p>To add an image, click the upload area or drag and drop files into it.</p><p>This section includes the following features:</p><ul><li>Select one or more images: You can upload multiple images at the same time.</li><li>Featured image (Index Image): The first and/or second image can be designated as the featured image.</li><li>Change the featured image: According to the instructions shown in the form, double-click an image to make it the featured image.</li><li>Delete an image: Use the delete button below the relevant image.</li></ul><p>Note: The featured image should show the product clearly and attractively, as it may appear in product listings, on the product details page, and in other sections of the site.</p><h2 id="step-3-additional-data" tabindex="-1">Step 3: Additional Data <a class="header-anchor" href="#step-3-additional-data" aria-label="Permalink to “Step 3: Additional Data”">​</a></h2><p><img src="`+o+`" alt="product3.webp" width="1856" height="1793"> Image reference: Second submitted image - Additional Data form</p><p>This step includes additional product settings, general inventory, categories, specifications, discounts, attachments, and structured data.</p><h3 id="_3-1-product-inventory-and-status" tabindex="-1">3.1. Product Inventory and Status <a class="header-anchor" href="#_3-1-product-inventory-and-status" aria-label="Permalink to “3.1. Product Inventory and Status”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Stock quantity</td><td>The product&#39;s inventory count. If the product has quantity options, this value can be updated automatically from the sum of the options&#39; inventory counts.</td></tr><tr><td>Status</td><td>The product&#39;s inventory status. The defined values are <code>IN_STOCK</code>, <code>OUT_STOCK</code>, and <code>BACK_ORDER</code>.</td></tr><tr><td>Tags</td><td>Tags associated with the product for topic-based categorization and to help search for and retrieve content.</td></tr></tbody></table><p>Inventory status differs from inventory count. For example, a product may have the <code>IN_STOCK</code> status, but its inventory count must also be greater than zero for it to be considered available.</p><p>If the product has options such as color and storage capacity, configure each option&#39;s inventory in Step 4. In this case, the system can calculate the product&#39;s total inventory from the sum of the options&#39; inventory counts.</p><h3 id="_3-2-product-categories" tabindex="-1">3.2. Product Categories <a class="header-anchor" href="#_3-2-product-categories" aria-label="Permalink to “3.2. Product Categories”">​</a></h3><p>In this section, you can also associate the product with additional categories.</p><ul><li>The main category is set in Step 1.</li><li>In this section, you can select additional categories from the category tree.</li><li>Selecting multiple categories associates the product with multiple sections of the site; the main category is still managed through its dedicated field.</li></ul><h3 id="_3-3-canonical-url" tabindex="-1">3.3. Canonical URL <a class="header-anchor" href="#_3-3-canonical-url" aria-label="Permalink to “3.3. Canonical URL”">​</a></h3><p>The Canonical field is used in SEO to specify the product page&#39;s canonical URL.</p><p>Use this field when you want search engines to treat a specific URL as the primary version of the content; for example, when similar content is accessible from multiple URLs.</p><p>If you do not need a custom canonical URL, leave the value unchanged.</p><h3 id="_3-4-product-type-virtual-and-downloadable" tabindex="-1">3.4. Product Type: Virtual and Downloadable <a class="header-anchor" href="#_3-4-product-type-virtual-and-downloadable" aria-label="Permalink to “3.4. Product Type: Virtual and Downloadable”">​</a></h3><p>Virtual product - Virtual product</p><p>Use this option for products or services that do not require physical shipping. Enabling it identifies the product as virtual.</p><p>Downloadable product - Downloadable product</p><p>Use this option for products whose purchase provides access to downloadable files, such as an e-book, a learning resource, or digital content.</p><p>These options serve different purposes and can be configured as needed for the product type.</p><h3 id="_3-5-description-table" tabindex="-1">3.5. Description Table <a class="header-anchor" href="#_3-5-description-table" aria-label="Permalink to “3.5. Description Table”">​</a></h3><p>Use this section to record structured product information in a table.</p><p>Use it to display technical specifications or additional product information, such as comparison details, model information, or specifications that you want displayed in a table on the product page.</p><p>This section is managed with a Rich Text Editor, so you can adjust the table content and formatting to suit the product.</p><h3 id="_3-6-discounts" tabindex="-1">3.6. Discounts <a class="header-anchor" href="#_3-6-discounts" aria-label="Permalink to “3.6. Discounts”">​</a></h3><p>You can manage product-related discounts in the Discounts section. Use the Add new discount button to add a discount.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Title</td><td>The discount title, used to identify it in the admin panel.</td></tr><tr><td>Type</td><td>Discount type: <code>PRICE</code> for a fixed amount and <code>PERCENT</code> for a percentage discount.</td></tr><tr><td>Amount</td><td>The discount amount: a monetary amount for a fixed discount, or a number from zero to one hundred for a percentage discount.</td></tr><tr><td>Discount code</td><td>The discount code, which can be used in the cart for code-based discounts.</td></tr><tr><td>Expire date</td><td>The discount&#39;s expiration date and time. If left blank, no expiration date is set.</td></tr></tbody></table><p>The difference between fixed-amount and percentage discounts:</p><ul><li>A fixed-amount discount subtracts a specific amount from the price.</li><li>A percentage discount reduces the price by a percentage.</li></ul><p>In the system model, a discount associated with a specific product is linked to that product through <code>product_id</code>. If this field is blank, the discount is considered general and is not assigned to a specific product.</p><h3 id="_3-7-product-attachments" tabindex="-1">3.7. Product Attachments <a class="header-anchor" href="#_3-7-product-attachments" aria-label="Permalink to “3.7. Product Attachments”">​</a></h3><p>You can add files related to the product in the Attachments section, such as a user guide, PDF, learning resource, or digital files.</p><p>Adding an attachment</p><p>Use the add button to attach the desired file to the product. Attachments can have access settings in addition to a title and file name.</p><p>Premium Attachment</p><p>The shield icon indicates that an attachment has special access. Enable the switch next to it to mark the attachment as premium.</p><p>File access works as follows:</p><ul><li>A guest user or a customer who has not purchased the product: Can access only non-premium attachments.</li><li>A signed-in customer who has purchased the product: Can access both non-premium and premium attachments.</li></ul><p>Therefore, if a file should be available only to customers who have purchased the product, mark it as a premium attachment.</p><h3 id="_3-8-product-schema-markup" tabindex="-1">3.8. Product Schema Markup <a class="header-anchor" href="#_3-8-product-schema-markup" aria-label="Permalink to “3.8. Product Schema Markup”">​</a></h3><p>At the end of this step, the Markups section is available for configuring the product&#39;s Schema Markup.</p><p>Schema Markup is structured data that helps search engines better understand the content type and its information. In this section, you can define or edit the Markup template for the product.</p><p>For information about the editor, supported keywords, buttons for automatically inserting values, Syntax selection, and Reset behavior, refer to the Schema Markup editor documentation.</p><h2 id="step-4-inventory-and-quantity-options" tabindex="-1">Step 4: Inventory and Quantity Options <a class="header-anchor" href="#step-4-inventory-and-quantity-options" aria-label="Permalink to “Step 4: Inventory and Quantity Options”">​</a></h2><p><img src="`+s+`" alt="product4.webp" width="1843" height="762"> Image reference: First submitted image - Quantities form</p><p>This step applies to products offered in multiple variations or combinations, such as different colors, storage capacities, or combinations of several features.</p><p>For example, a phone may be available in Rose Gold with 64 GB and 128 GB storage capacities. Each combination can have its own price and inventory count.</p><h3 id="_4-1-defining-product-options" tabindex="-1">4.1. Defining Product Options <a class="header-anchor" href="#_4-1-defining-product-options" aria-label="Permalink to “4.1. Defining Product Options”">​</a></h3><p>Enter the features for a product option in each row.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Color</td><td>The color of the product option. A color input may be provided to make color selection easier.</td></tr><tr><td>Warranty</td><td>The warranty status or type for the option.</td></tr><tr><td>Internal storage</td><td>The internal storage capacity or a similar feature, depending on the specifications defined for the product.</td></tr><tr><td>Count</td><td>The inventory count for this option.</td></tr><tr><td>Price</td><td>The price for this option.</td></tr></tbody></table><p>Use the add button to create a new option. Each row represents a specific combination of features and can have a different quantity and price.</p><p>For example:</p><table tabindex="0"><thead><tr><th>Color</th><th>Storage</th><th>Count</th><th>Price</th></tr></thead><tbody><tr><td>Rose Gold</td><td>64 GB</td><td>1</td><td>3000</td></tr><tr><td>Rose Gold</td><td>128 GB</td><td>1</td><td>3200</td></tr></tbody></table><p>In this example, the total inventory across the options is 2 units.</p><h3 id="_4-2-how-options-relate-to-product-inventory" tabindex="-1">4.2. How Options Relate to Product Inventory <a class="header-anchor" href="#_4-2-how-options-relate-to-product-inventory" aria-label="Permalink to “4.2. How Options Relate to Product Inventory”">​</a></h3><p>The inventory defined in this step is linked to the product&#39;s overall inventory.</p><p>According to the Product model logic, the <code>renewPriceAndStock()</code> method, when quantity options exist:</p><ul><li>Calculates the product&#39;s inventory count from the sum of the options&#39; <code>count</code> values.</li><li>Sets the product&#39;s base price based on the lowest price among options with an inventory count greater than zero.</li></ul><p>Therefore, for products with options, carefully configure the price and inventory for each combination in this step. The product&#39;s overall inventory count can be updated automatically from this information.</p><p>Note: In the current implementation, calculating the base price depends on at least one option having a positive inventory count. If no options are in stock, check the current system logic to determine how the price behaves.</p><h3 id="_4-3-where-are-features-defined" tabindex="-1">4.3. Where Are Features Defined? <a class="header-anchor" href="#_4-3-where-are-features-defined" aria-label="Permalink to “4.3. Where Are Features Defined?”">​</a></h3><p>The options available in this step depend on features defined in the feature management section and Properties Meta.</p><p>In simple terms:</p><ul><li>First, define features such as color, warranty, or storage capacity.</li><li>Then, make these features available for the product.</li><li>In Step 4, create the desired combinations and set the quantity and price for each one.</li></ul><p>If a required feature is not available in this step, first check its definition in the feature management section. <a href="./05-props.html">Properties Meta Documentation</a></p><h2 id="navigation-and-publication-buttons" tabindex="-1">Navigation and Publication Buttons <a class="header-anchor" href="#navigation-and-publication-buttons" aria-label="Permalink to “Navigation and Publication Buttons”">​</a></h2><p>Navigation and publication buttons are located at the bottom of the wizard steps.</p><table tabindex="0"><thead><tr><th>Button</th><th>Purpose</th></tr></thead><tbody><tr><td>Previous</td><td>Return to the previous step to review or edit information.</td></tr><tr><td>Next</td><td>Move to the next step to continue completing the form.</td></tr><tr><td>Publish</td><td>Save and publish the product according to the system&#39;s publication status and logic.</td></tr></tbody></table><p>Before final publication, review the product&#39;s basic information, images, categories, prices, inventory, and attachments. If the product has premium files, also check their access settings.</p><h2 id="recommended-pre-publication-checklist" tabindex="-1">Recommended Pre-Publication Checklist <a class="header-anchor" href="#recommended-pre-publication-checklist" aria-label="Permalink to “Recommended Pre-Publication Checklist”">​</a></h2><ul><li>The product name, Slug, and main category are complete.</li><li>The base price and purchase price have been entered correctly.</li><li>The product description has been reviewed, and important SEO suggestions have been considered.</li><li>Product images have been uploaded, and an appropriate featured image has been selected.</li><li>Additional categories and tags have been configured.</li><li>The inventory status matches the product&#39;s actual quantity.</li><li>If quantity options are available, the price and count for each option have been reviewed.</li><li>Discounts and their expiration dates have been checked.</li><li>Premium attachments and file access levels have been reviewed.</li><li>Canonical and Schema Markup have been configured if needed.</li></ul><p>Together, these four steps cover the complete product creation and editing process, from entering initial information and images to configuring features, managing inventory, and publishing the product on the site.</p>`,99)]])}var d=n(l,[[`render`,u]]);export{c as __pageData,d as default};